      "output": "(()=>{const F=window.F,S=F.SHEET,K=S.walk,P=S.rig.pivots,D=Math.PI/180,E=F.ease.inOut,R=F.remap,M=Math,N=K.order;\nconst sh=S.shots,s3=sh.find(s=>s.id==='s03'),cy=K.cycle,st=K.stance*cy,v=K.speed;\nconst mx=String(K.rootX||'').match(/=\\s*(-?[\\d.]+)/),x0=mx?parseFloat(mx[1]):K.platform.center[0]-v*K.stop;\nconst rx=T=>x0+v*M.min(T,K.stop);\nconst PL={};N.forEach(L=>{const a=S.cues.filter(c=>c.kind==='footfall'&&c.leg===L).map(c=>c.t).sort((p,q)=>p-q);a.unshift((a.length?a[0]:K.firstFootfall)-cy);PL[L]=a;});\nconst sit=K.sit,how=K.howl,set=K.settle,jo=K.jawOpenDeg*D,hl=K.headLiftDeg*D,bo=K.bob,tl=K.tailSwing.amplitudeDeg*D;\nlet G=null,V=null;\nconst geo=w=>{if(G)return G;const T3=F.THREE;V=new T3.Vector3();const g={L:{}},bp=w.body.position;\ng.hd=M.hypot(w.head.position.x||P.head[0],w.head.position.y||0)||P.head[0];\nN.forEach(L=>{const l=w.legs[L],u=l.upper.position,a=l.lower.position.length()||P.upperLength,b=l.foot.position.length()||P.lowerLength;\nconst hy=bp.y+u.y;const h=P.footHeight;g.L[L]={a,b,h,hx:bp.x+u.x,hz:bp.z+u.z,fr:L[1]==='F'};});\nreturn G=g;};\nconst fx=(L,p)=>G.L[L].hx+rx(p+st/2);\nconst ik=(l,q,dx,dy,fr,th)=>{const a=q.a,b=q.b;let d=M.hypot(dx,dy);d=F.clamp(d,M.abs(a-b)+1e-4,(a+b)*0.9995);\nconst ph=M.atan2(dx,-dy),al=M.acos(F.clamp((a*a+d*d-b*b)/(2*a*d),-1,1)),ga=M.acos(F.clamp((a*a+b*b-d*d)/(2*a*b),-1,1)),s=fr?-1:1;\nconst u=ph+s*al,lo=-s*(M.PI-ga);l.upper.rotation.set(0,0,u-th);l.lower.rotation.set(0,0,lo);return u+lo;};\nconst ft=(L,T)=>{const a=PL[L];let i=0;while(i+1<a.length&&a[i+1]<=T)i++;const t0=a[i],t1=a[i+1];\nif(T<t0+st||t1===undefined)return{p:fx(L,t0),k:-1};const k=(T-t0-st)/(t1-t0-st);return{p0:fx(L,t0),p:fx(L,t1),k};};\nconst pose=T=>{const w=F.wolf;if(!w||!w.root||!w.legs||!w.body)return;const g=geo(w),q=g.L,bp=w.body.position;\nconst X=rx(T),ks=E(R(T,sit[0],sit[1],0,1)),dt=M.max(0,T-K.stop),nd=T>K.stop?F.spring(dt,0.8,0.6)-F.clamp(dt/0.6,0,1):0,kw=1-R(T,K.stop-0.25,K.stop,0,1);\nconst bb=-bo.amplitude*(1-M.cos(2*M.PI*bo.perCycle*(T-K.firstFootfall)/cy))/2*kw;\nconst th=M.asin(F.clamp(-bb/g.hd,-1,1))+20*D*ks,ry=-0.04+bb-0.15*ks;\nw.root.position.set(X,ry,w.root.position.z);w.body.rotation.set(0,0,th);\nconst c=M.cos(th),s=M.sin(th);\nN.forEach(L=>{const l=w.legs[L],z=q[L],u=l.upper.position,f=ft(L,T);\nconst hx=bp.x+u.x*c-u.y*s,hy=ry+bp.y+u.x*s+u.y*c;let ax,ay=z.h;\nif(f.k<0)ax=f.p;else{ax=F.lerp(f.p0,f.p,E(f.k));ay+=0.09*M.sin(M.PI*f.k);}\nconst sm=ik(l,z,ax-X-hx,ay-hy,z.fr,th);l.foot.rotation.set(0,0,-sm+(f.k<0?0:0.5*M.sin(M.PI*f.k)*(z.fr?-1:1)));});\nconst hk=hl*ks*(1-0.45*E(R(T,set[0],set[1],0,1)))+4*D*nd;w.head.rotation.set(0,0,-th+hk);\nconst jk=E(R(T,how[0],how[0]+0.5,0,1))*(1-E(R(T,how[1]-0.2,set[0]+0.6,0,1)));if(w.jaw)w.jaw.rotation.set(0,0,-jo*jk);\nconst ta=w.tail||[],n=ta.length||1,wt=tl*(1-0.7*ks);ta.forEach((t,i)=>t.rotation.set(0,wt/n*1.4*M.sin(2*M.PI*K.tailSwing.perCycle*T/cy-i*0.5),i?0.04:-th*0.3-0.25*ks));};\nconst ens=r=>{const o=new F.THREE.Object3D();o.name='gait';r.add(o);};\nF.scene(\"gait-pose\",{start:0,end:F.LENGTH,setup:ens,update:T=>pose(T)});\nF.scene(s3.id,{start:s3.start,end:s3.end,setup:ens,update:T=>pose(T)});\nF.test('gait: planted feet move under 2 mm',()=>{const w=F.wolf;if(!w||!w.root)return{ok:false,detail:'no F.wolf'};\nlet m=0,n=0;const A=new F.THREE.Vector3(),B=new F.THREE.Vector3(),W=(t,v)=>{pose(t);w.root.updateMatrixWorld(true);w.legs[L0].foot.getWorldPosition(v);};let L0;\nN.forEach(L=>{L0=L;PL[L].forEach(t0=>{if(t0<0||t0>K.stop)return;W(t0+0.01,A);W(t0+st-0.02,B);m=M.max(m,A.distanceTo(B));n++;});});\nreturn{ok:n>0&&m<0.002,detail:n+' stances, max drift '+(m*1000).toFixed(2)+' mm'};});\n})();\n",
