      "output": "(()=>{const F=window.F,T=F.THREE,S=F.SHEET,L=S.look,P=S.palette,E=S.set,M=L.materials,PI=Math.PI,R=F.rand(9127),O=new T.Object3D();\nconst sm=(c,m,r,x)=>new T.MeshStandardMaterial(Object.assign({color:c,metalness:m,roughness:r},x||{}));\nconst mt=k=>sm(M[k].color,M[k].metalness,M[k].roughness);\nconst mk=(g,m,p,r,par,sh)=>{const o=new T.Mesh(g,m);if(p)o.position.set(p[0],p[1],p[2]);if(r)o.rotation.set(r[0],r[1],r[2]);o.castShadow=!!sh;o.receiveShadow=true;par.add(o);return o};\nconst ins=(g,m,a,par,sh)=>{const o=new T.InstancedMesh(g,m,a.length);a.forEach((q,i)=>{O.position.set(q[0],q[1],q[2]);O.rotation.set(q[3]||0,q[4]||0,q[5]||0);O.scale.setScalar(q[6]||1);O.updateMatrix();o.setMatrixAt(i,O.matrix)});o.instanceMatrix.needsUpdate=true;o.castShadow=!!sh;o.receiveShadow=true;par.add(o);return o};\nconst cyl=(a,b,h,s,o)=>new T.CylinderGeometry(a,b,h,s||16,1,!!o),box=(x,y,z)=>new T.BoxGeometry(x,y,z);\nconst gearG=(n,r)=>{const s=new T.Shape(),ri=r*0.85,k=n*4;for(let i=0;i<=k;i++){const a=i/k*PI*2,rr=(i%4<2)?r:ri,x=Math.cos(a)*rr,y=Math.sin(a)*rr;i?s.lineTo(x,y):s.moveTo(x,y)}\nconst h=new T.Path();h.absarc(0,0,r*0.16,0,PI*2,true);s.holes.push(h);const nh=n>18?5:4;for(let j=0;j<nh;j++){const a=j/nh*PI*2,q=new T.Path();q.absarc(Math.cos(a)*r*0.52,Math.sin(a)*r*0.52,r*0.17,0,PI*2,true);s.holes.push(q)}\nreturn new T.ExtrudeGeometry(s,{depth:0.06,bevelEnabled:false,curveSegments:5})};\nlet gears=[],needles=[],built=[];\nconst st=S.shots,t0=st[0].start,t1=st[st.length-1].end,s1=st.find(s=>s.module==='room')||st[0];\nfunction setup(root){built.push(root);const B=mt('brass'),C=mt('copper'),I=mt('iron'),D=sm(M.iron.color,0.6,0.75),FA=sm(P.ink,0,0.55),BU=sm(P.lampWarm,0,0.4,{emissive:P.lampWarm,emissiveIntensity:4});\nif(F.world)F.world.fog=new T.Fog(L.fog.color,L.fog.near,L.fog.far);\nconst W=E.walkway,x0=W.x[0],x1=W.x[1],len=x1-x0,cx=(x0+x1)/2,hw=W.width/2,pl=W.plate,y=W.y,np=Math.round(len/pl),pc=W.platform||S.walk.platform;\nconst pa=[],rv=[];for(let i=0;i<np;i++){const x=x0+pl*(i+0.5);pa.push([x,y-0.015,0]);for(const dx of[-1,1])for(const dz of[-1,1])rv.push([x+dx*(pl/2-0.04),y,dz*(hw-0.05)])}\nins(box(pl-0.012,0.03,W.width),I,pa,root);\nfor(const s of[-1,1]){mk(box(len,0.14,0.06),D,[cx,y-0.08,s*(hw+0.03)],0,root);for(let x=x0+0.25;x<x1;x+=0.5)rv.push([x,y-0.05,s*(hw+0.06),PI/2,0,0])}\nconst jo=[];for(let x=x0+0.5;x<x1;x+=1)jo.push([x,y-0.12,0]);ins(box(0.08,0.1,W.width),D,jo,root);\nconst pf=S.walk.platform,px=pf.center[0],pz=pf.center[2],pr=pf.radius;\nmk(cyl(pr,pr,0.06,48),I,[px,y-0.026,pz],0,root);mk(new T.TorusGeometry(pr,0.025,6,48),B,[px,y+0.002,pz],[PI/2,0,0],root);mk(new T.TorusGeometry(pr*0.55,0.012,4,40),C,[px,y+0.003,pz],[PI/2,0,0],root);\nfor(let i=0;i<24;i++){const a=i/24*PI*2;rv.push([px+Math.cos(a)*(pr-0.07),y+0.004,pz+Math.sin(a)*(pr-0.07)])}\nmk(cyl(pr*1.02,pr*0.7,0.5,24,1),D,[px,y-0.3,pz],0,root);\nins(new T.SphereGeometry(0.014,6,3,0,PI*2,0,PI/2),B,rv,root);\nconst pp=E.pipes,fl=[],br=[];pp.heights.forEach((h,i)=>{mk(cyl(pp.radius,pp.radius,len,20,1),i==1?B:C,[cx,h,pp.z],[0,0,PI/2],root,1);for(let x=x0+0.75;x<x1;x+=1.5)fl.push([x,h,pp.z,0,0,PI/2])});\nins(cyl(pp.radius*1.22,pp.radius*1.22,0.07,20),B,fl,root,1);\nfor(let x=x0+1;x<x1;x+=3)br.push([x,0.85,pp.z-0.27]);ins(box(0.1,2.2,0.06),D,br,root);\nfor(const v of E.valveWheels){const g=new T.Group();g.position.set(v[0],v[1],v[2]);root.add(g);mk(new T.TorusGeometry(0.17,0.018,6,24),B,0,0,g,1);for(let k=0;k<3;k++)mk(box(0.34,0.022,0.018),B,0,[0,0,k*PI/3+R()],g);mk(cyl(0.035,0.035,0.05,12),C,[0,0,0],[PI/2,0,0],g);mk(cyl(0.018,0.018,0.12,8),I,[0,0,-0.06],[PI/2,0,0],g)}\nconst G=E.gearWall,gz=G.z,tr=G.turnRadPerS;mk(box(len+6,6,0.1),D,[cx,1.5,gz-0.2],0,root);\nconst wr=[];for(let x=x0-2;x<x1+3;x+=1.2)for(let h=-0.5;h<4;h+=1.1)wr.push([x,h,gz-0.14,PI/2,0,0]);ins(cyl(0.025,0.025,0.03,6),B,wr,root);\nconst gg=[gearG(12,1),gearG(20,1)];for(let i=0;i<G.count;i++){const r=0.35+R()*0.75,g=mk(gg[i%2],i%3?B:C,[x0+(i+0.5)*(len/G.count)+(R()-0.5)*0.6,0.3+R()*2.6,gz+R()*0.08],0,root,0);g.scale.setScalar(r);mk(cyl(0.12*r,0.12*r,0.12,10),I,[g.position.x,g.position.y,gz+0.1],[PI/2,0,0],root);gears.push([g,(i%2?1:-1)*F.lerp(tr[0],tr[1],R()),R()*PI*2])}\nconst tk=[];for(let i=0;i<12;i++){const a=i/12*PI*2;tk.push([Math.cos(a)*0.1,Math.sin(a)*0.1,0.012,0,0,a])}\nfor(const q of E.gauges){const g=new T.Group();g.position.set(q[0],q[1],q[2]);root.add(g);mk(cyl(0.15,0.15,0.04,28),FA,0,[PI/2,0,0],g);mk(new T.TorusGeometry(0.15,0.022,6,28),B,0,0,g,1);mk(cyl(0.022,0.022,q[1]-E.pipes.heights[2],8),I,[0,-(q[1]-E.pipes.heights[2])/2-0.15,-0.04],0,g);ins(box(0.03,0.006,0.004),I,tk,g);\nconst n=new T.Group();n.position.z=0.026;g.add(n);mk(box(0.12,0.01,0.004),C,[0.045,0,0],0,n);mk(cyl(0.012,0.012,0.012,8),B,0,[PI/2,0,0],n);needles.push([n,R()*PI*0.8-PI*0.1,R()*PI*2])}\nconst cg=[];for(let k=0;k<6;k++){const a=k/6*PI*2;cg.push([Math.cos(a)*0.11,-0.02,Math.sin(a)*0.11])}\nfor(const q of E.lamps){const g=new T.Group();g.position.set(q[0],q[1],q[2]);root.add(g);mk(new T.SphereGeometry(0.06,12,8),BU,0,0,g);mk(cyl(0.07,0.12,0.06,16,1),C,[0,0.11,0],0,g);mk(cyl(0.012,0.012,1.6,6),I,[0,0.94,0],0,g);ins(cyl(0.006,0.006,0.24,4),B,cg,g);for(const h of[-0.13,0.09])mk(new T.TorusGeometry(0.11,0.008,4,20),B,[0,h,0],[PI/2,0,0],g)}\nconst k=L.lights.key,kl=new T.DirectionalLight(k.color,k.intensity);kl.position.set(...k.position);kl.target.position.set(k.position[0]-3,0,0);root.add(kl.target);\nif(L.shadows&&k.castShadow){kl.castShadow=true;const sc=k.shadowCamera,c=kl.shadow.camera;Object.assign(c,sc);c.updateProjectionMatrix();kl.shadow.mapSize.set(L.shadows.mapSize,L.shadows.mapSize);kl.shadow.bias=-0.0005;kl.shadow.normalBias=0.02}root.add(kl);\nconst f=L.lights.fill;root.add(new T.HemisphereLight(f.sky,f.ground,f.intensity))}\nfunction update(t){for(const[g,w,p]of gears)g.rotation.z=p+w*t;const a=S.set.needleTremble,d=a.deg*PI/180;for(const[n,b,p]of needles)n.rotation.z=b+d*Math.sin(2*PI*a.hz*t+p)}\nF.scene(s1.id,{start:t0,end:t1,setup,update});\nF.test('room set built',()=>{let n=0;built.forEach(r=>r.traverse(()=>n++));return{ok:built.length==1&&n>50&&gears.length==E.gearWall.count&&needles.length==E.gauges.length,detail:n+' objects, '+gears.length+' gears'}});\n})();\n",
